import { useState, forwardRef, useId, useEffect, useRef } from 'react'
import { createPortal } from 'react-dom'
import { ChevronDown, Check, AlertCircle } from 'lucide-react'

const Select = forwardRef(function Select(
  { label, hint, error, options = [], placeholder, className = '', value, onChange, children, ...props },
  ref,
) {
  const reactId = useId()
  const id = props.id || `sel-${reactId}`
  const triggerRef = useRef(null)
  const [open, setOpen] = useState(false)
  const [pos, setPos] = useState({ top: 0, left: 0, width: 0 })
  const [highlighted, setHighlighted] = useState(0)

  // Parse children if provided (for <option> elements)
  const parsedOptions = (() => {
    if (options.length > 0) return options
    if (!children) return []
    const arr = []
    const walk = (nodes) => {
      nodes.forEach((node) => {
        if (!node) return
        if (Array.isArray(node)) walk(node)
        else if (node.type === 'option') arr.push({ value: node.props.value, label: node.props.children })
      })
    }
    walk(Array.isArray(children) ? children : [children])
    return arr
  })()

  const selected = parsedOptions.find((o) => String(o.value) === String(value))

  useEffect(() => {
    if (!open) return
    const update = () => {
      const r = triggerRef.current?.getBoundingClientRect()
      if (r) setPos({ top: r.bottom + 6, left: r.left, width: r.width })
    }
    update()
    window.addEventListener('scroll', update, true)
    window.addEventListener('resize', update)
    const onKey = (e) => {
      if (e.key === 'Escape') {
        setOpen(false)
        triggerRef.current?.focus()
      } else if (e.key === 'ArrowDown') {
        e.preventDefault()
        setHighlighted((h) => Math.min(h + 1, parsedOptions.length - 1))
      } else if (e.key === 'ArrowUp') {
        e.preventDefault()
        setHighlighted((h) => Math.max(h - 1, 0))
      } else if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault()
        const opt = parsedOptions[highlighted]
        if (opt) {
          onChange?.({ target: { value: opt.value } })
          setOpen(false)
        }
      }
    }
    document.addEventListener('keydown', onKey)
    document.addEventListener('mousedown', (e) => {
      if (triggerRef.current?.contains(e.target)) return
      if (e.target.closest(`[data-select-menu="${id}"]`)) return
      setOpen(false)
    })
    return () => {
      window.removeEventListener('scroll', update, true)
      window.removeEventListener('resize', update)
      document.removeEventListener('keydown', onKey)
    }
  }, [open, id, highlighted, parsedOptions, onChange])

  useEffect(() => {
    if (open) {
      const idx = parsedOptions.findIndex((o) => String(o.value) === String(value))
      setHighlighted(idx >= 0 ? idx : 0)
    }
  }, [open, value, parsedOptions])

  const handleSelect = (val) => {
    onChange?.({ target: { value: val } })
    setOpen(false)
    triggerRef.current?.focus()
  }

  return (
    <div className={className}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-xs font-medium text-foreground">
          {label}
        </label>
      )}
      <button
        type="button"
        id={id}
        ref={(el) => {
          triggerRef.current = el
          if (typeof ref === 'function') ref(el)
          else if (ref) ref.current = el
        }}
        onClick={() => !props.disabled && setOpen((v) => !v)}
        disabled={props.disabled}
        className={`group relative flex w-full cursor-pointer items-center rounded-lg border bg-surface px-3 py-2.5 pr-9 text-left text-sm text-foreground transition-all duration-150 ${
          error
            ? 'border-danger focus:border-danger focus:ring-2 focus:ring-danger/20'
            : open
              ? 'border-primary ring-2 ring-primary/20 shadow-sm'
              : 'border-border hover:border-border-strong hover:shadow-xs'
        } disabled:cursor-not-allowed disabled:opacity-60`}
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <span className={selected ? '' : 'text-muted-foreground'}>
          {selected ? selected.label : placeholder || '—'}
        </span>
        <ChevronDown
          size={16}
          className={`pointer-events-none absolute right-3 text-muted-foreground transition-transform duration-200 ${
            open ? 'rotate-180 text-primary' : ''
          }`}
        />
      </button>
      {open &&
        createPortal(
          <div
            data-select-menu={id}
            className="animate-scale-in fixed z-[300] max-h-60 overflow-y-auto rounded-lg border border-border bg-surface shadow-pop"
            style={{ top: pos.top, left: pos.left, width: pos.width }}
            role="listbox"
          >
            <div className="p-1">
              {parsedOptions.length === 0 ? (
                <p className="px-3 py-2 text-sm text-muted-foreground">—</p>
              ) : (
                parsedOptions.map((o, idx) => {
                  const isSel = String(o.value) === String(value)
                  const isH = idx === highlighted
                  return (
                    <button
                      key={String(o.value)}
                      type="button"
                      role="option"
                      aria-selected={isSel}
                      onClick={() => handleSelect(o.value)}
                      onMouseEnter={() => setHighlighted(idx)}
                      className={`flex w-full cursor-pointer items-center justify-between gap-2 rounded-md px-2.5 py-2 text-left text-sm transition-colors duration-100 ${
                        isSel
                          ? 'bg-primary/15 font-medium text-primary-strong'
                          : isH
                            ? 'bg-surface-hover text-foreground'
                            : 'text-foreground'
                      }`}
                    >
                      <span className="truncate">{o.label}</span>
                      {isSel && <Check size={14} className="shrink-0 text-primary" />}
                    </button>
                  )
                })
              )}
            </div>
          </div>,
          document.body,
        )}
      {error ? (
        <p className="mt-1 flex items-center gap-1 text-xs text-danger">
          <AlertCircle size={12} />
          {error}
        </p>
      ) : hint ? (
        <p className="mt-1 text-xs text-muted-foreground">{hint}</p>
      ) : null}
    </div>
  )
})

export default Select

import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { ArrowLeft, Plus } from 'lucide-react'
import { useOrders } from '../../hooks/useOrders.js'
import { useCustomers } from '../../hooks/useCustomers.js'
import { useI18n } from '../../i18n/index.jsx'
import { useToast } from '../../context/ToastContext.jsx'
import { DEVICE_TYPES, DEVICE_TYPE_LABEL_KEY, DEVICE_BRANDS } from '../../constants/deviceTypes.js'
import { PRIORITIES, PRIORITY_LABEL_KEY } from '../../constants/priority.js'
import PageHeader from '../../components/common/PageHeader.jsx'
import Card from '../../components/common/Card.jsx'
import Input from '../../components/common/Input.jsx'
import Select from '../../components/common/Select.jsx'
import Textarea from '../../components/common/Textarea.jsx'
import Button from '../../components/common/Button.jsx'
import SegmentedControl from '../../components/common/SegmentedControl.jsx'

export default function CreateOrder() {
  const { t } = useI18n()
  const { createOrder, addPayment } = useOrders()
  const { customers, createCustomer } = useCustomers()
  const { workers } = useApp()
  const toast = useToast()
  const navigate = useNavigate()

  const [mode, setMode] = useState('existing')
  const [form, setForm] = useState({
    customerId: '',
    customerName: '',
    phone: '',
    deviceType: 'sedan',
    brand: '',
    model: '',
    year: '',
    plate: '',
    issue: '',
    price: '',
    paid: '',
    priority: 'normal',
    notes: '',
  })
  const [error, setError] = useState('')
  const [saving, setSaving] = useState(false)

  const brands = DEVICE_BRANDS[form.deviceType] || []
  const customerOptions = useMemo(
    () => customers.map((c) => ({ value: c.id, label: `${c.name} — ${c.phone}` })),
    [customers],
  )

  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }))

  const submit = async (e) => {
    e.preventDefault()
    setError('')
    if (mode === 'new' && !form.customerName.trim()) {
      setError(t('validation.required'))
      return
    }
    if (!form.issue.trim()) {
      setError(t('validation.required'))
      return
    }
    setSaving(true)
    try {
      let customerId = form.customerId
      let customerName = ''
      let phone = ''
      if (mode === 'new') {
        const customer = await createCustomer({
          name: form.customerName.trim(),
          phone: form.phone,
        })
        customerId = customer.id
        customerName = customer.name
        phone = customer.phone
      } else {
        const customer = customers.find((c) => c.id === form.customerId)
        customerName = customer?.name || ''
        phone = customer?.phone || ''
      }
      const order = await createOrder({
        customerId,
        customerName,
        phone,
        carType: form.deviceType,
        make: form.brand,
        model: form.model,
        year: Number(form.year) || null,
        plate: form.plate,
        issue: form.issue,
        priority: form.priority,
        price: Number(form.price) || 0,
        notes: form.notes,
      })
      const initialPaid = Number(form.paid) || 0
      if (initialPaid > 0) {
        await addPayment({ orderId: order.id, amount: initialPaid, method: 'cash' })
      }
      toast.success('toasts.orderCreated')
      navigate(`/orders/${order.id}`)
    } catch {
      setError(t('error.title'))
    } finally {
      setSaving(false)
    }
  }

  return (
    <div>
      <PageHeader title={t('orders.create.title')} subtitle={t('orders.create.subtitle')}>
        <Button variant="ghost" icon={ArrowLeft} onClick={() => navigate('/orders')}>
          {t('common.back')}
        </Button>
      </PageHeader>

      <form onSubmit={submit} className="space-y-4">
        <Card className="p-5">
          <SegmentedControl
            value={mode}
            onChange={setMode}
            options={[
              { value: 'existing', label: t('orders.create.existingCustomer') },
              { value: 'new', label: t('orders.create.newCustomer') },
            ]}
          />
          <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2">
            {mode === 'existing' ? (
              <Select
                label={t('orders.create.selectCustomer')}
                required
                value={form.customerId}
                onChange={set('customerId')}
                options={customerOptions}
                placeholder={t('orders.create.selectCustomer')}
                className="sm:col-span-2"
              />
            ) : (
              <>
                <Input label={t('orders.create.customerName')} required value={form.customerName} onChange={set('customerName')} />
                <Input label={t('orders.create.customerPhone')} value={form.phone} onChange={set('phone')} placeholder="+998 90 000 00 00" />
              </>
            )}
          </div>
        </Card>

        <Card className="p-5">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <Select
              label={t('orders.create.deviceType')}
              required
              value={form.deviceType}
              onChange={set('deviceType')}
              options={DEVICE_TYPES.map((d) => ({ value: d, label: t(DEVICE_TYPE_LABEL_KEY[d]) }))}
            />
            <Select
              label={t('orders.create.brand')}
              value={form.brand}
              onChange={set('brand')}
              options={brands.map((b) => ({ value: b, label: b }))}
              placeholder={t('orders.create.brand')}
            />
            <Input label={t('orders.create.model')} value={form.model} onChange={set('model')} placeholder="Captiva" />
            <Input label={t('orders.create.plate')} value={form.plate} onChange={set('plate')} placeholder="01 A 123 BC" />
            <Input label={t('orders.create.year')} type="number" min="1980" max="2026" value={form.year} onChange={set('year')} placeholder="2018" />
            <Textarea
              label={t('orders.create.issue')}
              required
              value={form.issue}
              onChange={set('issue')}
              placeholder={t('orders.create.issuePlaceholder')}
              rows={2}
              className="sm:col-span-2 lg:col-span-3"
            />
          </div>
        </Card>

        <Card className="p-5">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Input
              label={t('orders.create.price')}
              type="number"
              min="0"
              value={form.price}
              onChange={set('price')}
              placeholder="0"
            />
            <Input
              label={t('orders.paidAmount')}
              type="number"
              min="0"
              value={form.paid}
              onChange={set('paid')}
              placeholder="0"
            />
            <Select
              label={t('orders.create.priority')}
              value={form.priority}
              onChange={set('priority')}
              options={PRIORITIES.map((p) => ({ value: p, label: t(PRIORITY_LABEL_KEY[p]) }))}
            />
            <Textarea
              label={t('orders.create.notes')}
              value={form.notes}
              onChange={set('notes')}
              rows={2}
              placeholder={t('common.optional')}
            />
          </div>
          {error && <p className="mt-3 text-sm text-danger">{error}</p>}
        </Card>

        <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
          <Button variant="ghost" type="button" onClick={() => navigate('/orders')}>
            {t('common.cancel')}
          </Button>
          <Button type="submit" loading={saving} icon={Plus}>
            {t('orders.create.title')}
          </Button>
        </div>
      </form>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { Plus, Wrench } from 'lucide-react'
import { useOrders } from '../../hooks/useOrders.js'
import { useApp } from '../../context/AppContext.jsx'
import { useAuth } from '../../context/AuthContext.jsx'
import { useI18n } from '../../i18n/index.jsx'
import { useDebounce } from '../../hooks/useDebounce.js'
import {
  ORDER_STATUSES,
  ORDER_STATUS_LABEL_KEY,
  ORDER_STATUS_TONE,
} from '../../constants/orderStatus.js'
import {
  getPaymentStatus,
  PAYMENT_STATUS_LABEL_KEY,
  PAYMENT_STATUS_TONE,
} from '../../constants/paymentStatus.js'
import { formatDate } from '../../utils/formatDate.js'
import { formatCurrency } from '../../utils/formatCurrency.js'
import PageHeader from '../../components/common/PageHeader.jsx'
import SearchInput from '../../components/common/SearchInput.jsx'
import Select from '../../components/common/Select.jsx'
import Button from '../../components/common/Button.jsx'
import Badge from '../../components/common/Badge.jsx'
import Table from '../../components/common/Table.jsx'
import Card from '../../components/common/Card.jsx'
import { SkeletonRows } from '../../components/common/Skeleton.jsx'

export default function OrdersList() {
  const { t } = useI18n()
  const { orders } = useOrders()
  const { workers, loading } = useApp()
  const { user } = useAuth()
  const navigate = useNavigate()
  // Faqat consumer (CUSTOMER) yangi buyurtma berishi mumkin.
  const canCreate = user?.role === 'CUSTOMER'

  const [search, setSearch] = useState('')
  const [status, setStatus] = useState('all')
  const [worker, setWorker] = useState('all')
  const debounced = useDebounce(search)

  const filtered = useMemo(() => {
    const q = debounced.trim().toLowerCase()
    return orders
      .filter((o) => {
        if (status !== 'all' && o.status !== status) return false
        if (worker !== 'all' && o.workerId !== worker) return false
        if (!q) return true
        const hay = `${o.id} ${o.customerName} ${o.phone} ${o.make} ${o.model} ${o.plate} ${o.issue} ${o.workerName}`
        return hay.toLowerCase().includes(q)
      })
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
  }, [orders, debounced, status, worker])

  const columns = [
    { key: 'id', header: t('orders.col.id'), render: (o) => <span className="font-semibold text-foreground">{o.id}</span> },
    {
      key: 'customer',
      header: t('orders.col.customer'),
      render: (o) => (
        <div>
          <p className="font-medium text-foreground">{o.customerName}</p>
          <p className="font-mono text-xs text-muted">{o.phone}</p>
        </div>
      ),
    },
    {
      key: 'device',
      header: t('orders.col.device'),
      render: (o) => (
        <div>
          <p className="text-foreground">{o.make} {o.model}</p>
          <p className="text-xs text-muted">{o.plate}</p>
        </div>
      ),
    },
    {
      key: 'worker',
      header: t('orders.col.worker'),
      render: (o) => (o.workerName ? <span className="text-foreground">{o.workerName}</span> : <span className="text-muted">—</span>),
    },
    {
      key: 'status',
      header: t('orders.col.status'),
      render: (o) => <Badge tone={ORDER_STATUS_TONE[o.status]} dot>{t(ORDER_STATUS_LABEL_KEY[o.status])}</Badge>,
    },
    {
      key: 'payment',
      header: t('orders.col.payment'),
      render: (o) => (
        <Badge tone={PAYMENT_STATUS_TONE[getPaymentStatus(o.price, o.paid)]}>
          {t(PAYMENT_STATUS_LABEL_KEY[getPaymentStatus(o.price, o.paid)])}
        </Badge>
      ),
    },
    { key: 'price', header: t('orders.col.price'), align: 'right', render: (o) => <span className="font-medium tabular-nums text-foreground">{formatCurrency(o.price)}</span> },
    { key: 'date', header: t('orders.col.date'), render: (o) => <span className="text-muted-foreground">{formatDate(o.createdAt)}</span> },
  ]

  const mobileRender = (o) => (
    <Card key={o.id} as="button" type="button" className="p-4 text-left" onClick={() => navigate(`/orders/${o.id}`)}>
      <div className="flex items-center justify-between gap-2">
        <span className="font-semibold text-foreground">{o.id}</span>
        <Badge tone={ORDER_STATUS_TONE[o.status]} dot>{t(ORDER_STATUS_LABEL_KEY[o.status])}</Badge>
      </div>
      <div className="mt-1.5">
        <p className="text-sm font-medium text-foreground">{o.customerName}</p>
        <p className="truncate text-xs text-muted-foreground">{o.make} {o.model} · {o.plate}</p>
      </div>
      <div className="mt-2.5 flex items-center justify-between text-sm">
        <span className="font-medium tabular-nums text-foreground">{formatCurrency(o.price)}</span>
        <Badge tone={PAYMENT_STATUS_TONE[getPaymentStatus(o.price, o.paid)]}>
          {t(PAYMENT_STATUS_LABEL_KEY[getPaymentStatus(o.price, o.paid)])}
        </Badge>
      </div>
    </Card>
  )

  return (
    <div>
      <PageHeader title={t('orders.title')} subtitle={t('orders.subtitle')}>
        {canCreate && (
          <Link to="/orders/new">
            <Button icon={Plus}>{t('orders.create.title')}</Button>
          </Link>
        )}
      </PageHeader>

      <div className="mb-4 flex flex-col gap-2.5 sm:flex-row sm:items-center">
        <SearchInput value={search} onChange={setSearch} placeholder={t('orders.search')} className="sm:max-w-xs" />
        <Select
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          className="sm:w-48"
          aria-label={t('orders.filterStatus')}
        >
          <option value="all">{t('orders.filterStatus')}: {t('common.all')}</option>
          {ORDER_STATUSES.map((s) => (
            <option key={s} value={s}>{t(ORDER_STATUS_LABEL_KEY[s])}</option>
          ))}
        </Select>
        <Select
          value={worker}
          onChange={(e) => setWorker(e.target.value)}
          className="sm:w-48"
          aria-label={t('orders.filterWorker')}
        >
          <option value="all">{t('orders.filterWorker')}: {t('common.all')}</option>
          {workers.map((w) => (
            <option key={w.id} value={w.id}>{w.name}</option>
          ))}
        </Select>
      </div>

      {loading ? (
        <SkeletonRows count={6} />
      ) : (
      <Table
        columns={columns}
        rows={filtered}
        onRowClick={(o) => navigate(`/orders/${o.id}`)}
        mobileRender={mobileRender}
        empty={{
          icon: Wrench,
          title: t('orders.empty'),
          description: t('orders.emptyCta'),
          action: canCreate ? (
            <Link to="/orders/new">
              <Button size="sm" icon={Plus}>{t('orders.create.title')}</Button>
            </Link>
          ) : null,
        }}
      />
      )}
    </div>
  )
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import { ordersApi } from '../services/modules/ordersApi.js'
import { customersApi } from '../services/modules/customersApi.js'
import { paymentsApi } from '../services/modules/paymentsApi.js'
import { dashboardApi } from '../services/modules/dashboardApi.js'
import { workersApi } from '../services/modules/workersApi.js'
import { inventoryApi } from '../services/modules/inventoryApi.js'
import { systemApi } from '../services/modules/systemApi.js'
import { useAuth } from './AuthContext.jsx'

const AppContext = createContext(null)

function normalizeInventory(items) {
  return (items || []).map((i) => ({ ...i }))
}

function normalizeSettings(raw) {
  if (!raw) return null
  return {
    ...raw,
    business: {
      name: raw.businessName || '',
      phone: raw.businessPhone || '',
      address: raw.address || '',
      hours: raw.hours || '',
    },
  }
}

export function AppProvider({ children }) {
  const { user } = useAuth()
  const userId = user?.id || null
  const [loading, setLoading] = useState(!!userId)
  const [data, setData] = useState({
    orders: [],
    customers: [],
    payments: [],
    paymentsSummary: null,
    dashboard: null,
    activity: [],
    notifications: [],
    settings: null,
    workers: [],
    inventory: [],
  })

  const refresh = useCallback(async () => {
    const [orders, customers, payments, summary, dashboard, activity, notifications, settings, workers, inventory] =
      await Promise.all([
        ordersApi.list(),
        customersApi.list(),
        paymentsApi.list(),
        paymentsApi.summary().catch(() => ({ data: null })),
        dashboardApi.summary().catch(() => ({ data: null })),
        dashboardApi.activity(),
        systemApi.notifications(),
        systemApi.settings().catch(() => ({ data: null })),
        workersApi.list().catch(() => ({ data: [] })),
        inventoryApi.list(),
      ])
    setData({
      orders: orders.data || [],
      customers: customers.data || [],
      payments: payments.data || [],
      paymentsSummary: summary.data || null,
      dashboard: dashboard.data || null,
      activity: activity.data || [],
      notifications: notifications.data || [],
      settings: normalizeSettings(settings.data),
      workers: workers.data || [],
      inventory: normalizeInventory(inventory.data),
    })
  }, [])

  useEffect(() => {
    if (!userId) {
      setData({
        orders: [],
        customers: [],
        payments: [],
        paymentsSummary: null,
        dashboard: null,
        activity: [],
        notifications: [],
        settings: null,
        workers: [],
        inventory: [],
      })
      setLoading(false)
      return undefined
    }
    setLoading(true)
    refresh()
      .catch(() => {})
      .finally(() => setLoading(false))
  }, [userId, refresh])

  const wrap = useCallback(
    (fn) => async (...args) => {
      const result = await fn(...args)
      await refresh().catch(() => {})
      return result
    },
    [refresh],
  )

  const actions = useMemo(
    () => ({
      createOrder: wrap(async (input) => {
        const res = await ordersApi.create(input)
        return res.data
      }),
      updateOrderStatus: wrap(async (id, status) => {
        const res = await ordersApi.updateStatus(id, status)
        return res.data
      }),
      cancelOrder: wrap(async (id, reason) => {
        const res = await ordersApi.cancel(id, reason)
        return res.data
      }),
      assignWorker: wrap(async (id, workerId) => {
        const res = await ordersApi.assignWorker(id, workerId)
        return res.data
      }),
      addOrderNote: wrap(async (id, text) => {
