        return res.data
      }),
      refresh,
    }),
    [wrap, refresh],
  )

  const value = useMemo(
    () => ({
      ...data,
      loading,
      ...actions,
    }),
    [data, loading, actions],
  )

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

