    customerName: '',
    phone: '',
    deviceType: 'sedan',
    brand: '',
    model: '',
    year: '',
    plate: '',
    issue: '',
    price: '',
    paid: '',
    priority: 'normal',
    workerId: '',
    expectedDate: '',
    notes: '',
